mkdir -p /app/output && cat > /app/output/styles.css <<'EOF'
:root {
  --navy: #0a0a23;
  --navy-2: #151538;
  --amber: #f5b942;
  --amber-2: #f0a500;
  --bg: #f7f8fb;
  --surface: #ffffff;
  --text: #1c2230;
  --muted: #6a7280;
  --border: #e4e7ee;
  --success: #2f9e44;
  --radius: 14px;
  --shadow: 0 8px 30px rgba(10, 10, 35, 0.08);
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.55;
}
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
.container { width: min(1120px, 92%); margin: 0 auto; }
.site-header {
  background: var(--navy);
  color: #fff;
  position: sticky;
  top: 0;
  z-index: 30;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.nav-wrap { display: flex; align-items: center; justify-content: space-between; min-height: 74px; }
.brand { font-weight: 800; letter-spacing: 0.2px; font-size: 1.15rem; }
.brand span { color: var(--amber); }
.nav-links { display: flex; gap: 1.2rem; align-items: center; }
.nav-links a { color: rgba(255,255,255,0.88); font-weight: 600; }
.nav-links a:hover, .nav-links a.active { color: #fff; }
.cta-link {
  background: var(--amber);
  color: #111;
  padding: 0.55rem 0.95rem;
  border-radius: 999px;
  font-weight: 700;
}
.menu-btn {
  display: none;
  border: 1px solid rgba(255,255,255,0.3);
  color: #fff;
  background: transparent;
  border-radius: 10px;
  padding: 0.4rem 0.65rem;
  font-size: 1.05rem;
}
.mobile-menu {
  display: none;
  padding: 0 0 1rem;
}
.mobile-menu.open { display: grid; gap: 0.7rem; }
.mobile-menu a {
  display: block;
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.16);
  border-radius: 10px;
  padding: 0.72rem 0.85rem;
  color: #fff;
  font-weight: 600;
}
.hero {
  padding: 3rem 0 1.4rem;
}
.hero h1 { font-size: clamp(1.7rem, 3vw, 2.5rem); line-height: 1.2; margin: 0 0 0.75rem; }
.hero p { margin: 0; color: var(--muted); max-width: 760px; }
.section-title {
  margin: 1.8rem 0 1rem;
  font-size: 1.35rem;
}
.article-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.1rem;
}
.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
}
.thumb {
  height: 170px;
  background: linear-gradient(120deg, #23235a, #454593);
}
.card-content { padding: 0.95rem; }
.tag {
  display: inline-block;
  padding: 0.25rem 0.5rem;
  border-radius: 999px;
  font-size: 0.74rem;
  font-weight: 700;
  margin-bottom: 0.6rem;
}
.tag.ai { background: #ece9ff; color: #4d35d4; }
.tag.scraping { background: #e8fbf8; color: #0f8f7a; }
.tag.db { background: #fff3e0; color: #9a5c00; }
.tag.search { background: #e9f2ff; color: #2059ad; }
.tag.data { background: #f3f3f6; color: #4a4f5d; }
.card h3 {
  margin: 0 0 0.9rem;
  font-size: 1.03rem;
  line-height: 1.35;
}
.author-row {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  color: var(--muted);
  font-size: 0.85rem;
}
.avatar {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #dbe2ff;
  color: #2e3f8f;
  font-weight: 700;
  font-size: 0.8rem;
}
.center { text-align: center; }
.btn {
  border: 0;
  background: var(--navy);
  color: #fff;
  border-radius: 999px;
  padding: 0.72rem 1.1rem;
  font-weight: 700;
  cursor: pointer;
}
.btn:hover { background: var(--navy-2); }
.pill-row {
  display: flex;
  gap: 0.55rem;
  flex-wrap: wrap;
}
.pill {
  padding: 0.45rem 0.75rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: #fff;
  font-weight: 600;
  font-size: 0.86rem;
}
.learn-list, .stats-list {
  display: grid;
  gap: 0.7rem;
  padding: 0;
  margin: 1rem 0 0;
  list-style: none;
}
.learn-item, .stats-item {
  display: flex;
  gap: 0.7rem;
  align-items: center;
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 0.82rem 0.95rem;
}
.icon {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: #eef1fb;
  display: grid;
  place-items: center;
}
.donate-grid {
  display: grid;
  grid-template-columns: 1.25fr 1fr;
  gap: 1.1rem;
  align-items: start;
}
.panel {
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 1rem;
}
.amount-tabs { display: grid; grid-template-columns: repeat(4, 1fr); gap: 0.55rem; }
.amount-btn {
  border: 1px solid var(--border);
  background: #fff;
  border-radius: 10px;
  padding: 0.6rem 0.4rem;
  font-weight: 800;
  cursor: pointer;
}
.amount-btn.active { background: var(--amber); border-color: var(--amber-2); color: #111; }
.faq-item { border-top: 1px solid var(--border); }
.faq-q {
  width: 100%;
  border: 0;
  background: transparent;
  text-align: left;
  font-weight: 700;
  padding: 0.8rem 0;
  cursor: pointer;
}
.faq-a {
  max-height: 0;
  overflow: hidden;
  color: var(--muted);
  transition: max-height 0.3s ease;
}
.faq-item.open .faq-a { max-height: 120px; padding-bottom: 0.75rem; }
.footer {
  margin-top: 2.4rem;
  padding: 1.4rem 0;
  border-top: 1px solid var(--border);
  color: var(--muted);
  font-size: 0.9rem;
}
@media (max-width: 980px) {
  .article-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
  .donate-grid { grid-template-columns: 1fr; }
}
@media (max-width: 760px) {
  .nav-links { display: none; }
  .menu-btn { display: inline-block; }
  .article-grid { grid-template-columns: 1fr; }
}
EOF

